  QueueList(filter: Filter, sort: Sort): Promise<Msg[] | null>;
  QueueNextAttemptSet(filter: Filter, minutes: number): Promise<number>;
  QueueNextAttemptAdd(filter: Filter, minutes: number): Promise<number>;
  QueueHoldSet(filter: Filter, onHold: boolean): Promise<number>;
  QueueFail(filter: Filter): Promise<number>;
  QueueDrop(filter: Filter): Promise<number>;
  QueueRequireTLSSet(filter: Filter, requireTLS: boolean | null): Promise<number>;
  QueueTransportSet(filter: Filter, transport: string): Promise<number>;
  RetiredList(filter: RetiredFilter, sort: RetiredSort): Promise<MsgRetired[] | null>;
  HookQueueSize(): Promise<number>;
  HookList(filter: HookFilter, sort: HookSort): Promise<Hook[] | null>;
  HookNextAttemptSet(filter: HookFilter, minutes: number): Promise<number>;
  HookNextAttemptAdd(filter: HookFilter, minutes: number): Promise<number>;
  HookRetiredList(filter: HookRetiredFilter, sort: HookRetiredSort): Promise<HookRetired[] | null>;
  HookCancel(filter: HookFilter): Promise<number>;
  LogLevels(): Promise<{ [key: string]: string }>;
  LogLevelSet(pkg: string, levelStr: string): Promise<void>;
  LogLevelRemove(pkg: string): Promise<void>;
  CheckUpdatesEnabled(): Promise<boolean>;
  WebserverConfig(): Promise<WebserverConfig>;
