  Transports(): Promise<{ [key: string]: Transport }>;
  DMARCEvaluationStats(): Promise<{ [key: string]: EvaluationStat }>;
  DMARCEvaluationsDomain(domain: string): Promise<[Domain, Evaluation[] | null]>;
  DMARCRemoveEvaluations(domain: string): Promise<void>;
  DMARCSuppressAdd(reportingAddress: string, until: Date, comment: string): Promise<void>;
  DMARCSuppressList(): Promise<SuppressAddress[] | null>;
  DMARCSuppressRemove(id: number): Promise<void>;
  DMARCSuppressExtend(id: number, until: Date): Promise<void>;
  TLSRPTResults(): Promise<TLSResult[] | null>;
  TLSRPTResultsDomain(isRcptDom: boolean, policyDomain: string): Promise<[Domain, TLSResult[] | null]>;
  LookupTLSRPTRecord(domain: string): Promise<[TLSRPTRecord | null, string, string]>;
